  status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'accepted', 'declined')),
  invited_at timestamptz DEFAULT now(),
  responded_at timestamptz,
  UNIQUE(org_id, email)
);

CREATE INDEX idx_org_invites_email ON org_invites (email);
