ALTER TABLE org_invites ENABLE ROW LEVEL SECURITY;

-- Admin can manage invites for their own stations
drop policy if exists "admin_manage_invites" on org_invites;
CREATE POLICY "admin_manage_invites" ON org_invites
  FOR ALL USING (org_id IN (SELECT id FROM organizations WHERE owner_id = auth.uid()));

-- Users can read invites sent to their email
drop policy if exists "user_read_own_invites" on org_invites;
CREATE POLICY "user_read_own_invites" ON org_invites
  FOR SELECT USING (email = (SELECT email FROM users WHERE id = auth.uid()));


-- ─────────────────────────────────────────────
-- 010_station_subscriptions.sql
-- ─────────────────────────────────────────────

-- Link subscriptions to stations (one subscription per station)
-- Any user can be a station manager (no admin role needed)

-- 1. Add org_id to subscriptions (which station this subscription is for)
ALTER TABLE public.subscriptions
  ADD COLUMN org_id uuid REFERENCES public.organizations(id) ON DELETE SET NULL;

CREATE INDEX idx_subscriptions_org_id ON public.subscriptions(org_id);

-- 2. Users can read subscriptions for stations they own
drop policy if exists "manager_select_station_subs" on public.subscriptions;
CREATE POLICY "manager_select_station_subs" ON public.subscriptions
  FOR SELECT USING (
    org_id IN (SELECT id FROM public.organizations WHERE owner_id = auth.uid())
  );

-- 3. Users can insert subscriptions for stations they own
drop policy if exists "manager_insert_station_subs" on public.subscriptions;
CREATE POLICY "manager_insert_station_subs" ON public.subscriptions
  FOR INSERT WITH CHECK (
    auth.uid() = user_id AND
    org_id IN (SELECT id FROM public.organizations WHERE owner_id = auth.uid())
  );


