-- 012_onboarding_schema.sql
-- ─────────────────────────────────────────────

-- Onboarding schema updates for station setup wizard

-- 1. Add location and onboarding_complete flag to organizations
ALTER TABLE public.organizations
  ADD COLUMN location text,
  ADD COLUMN onboarding_complete boolean NOT NULL DEFAULT false;

-- 2. Add nozzle_label to station_pumps (e.g. "PUMP 1 N1")
--    Add tank_id FK for tank-to-nozzle mapping
ALTER TABLE public.station_pumps
  ADD COLUMN nozzle_label text,
  ADD COLUMN tank_id uuid REFERENCES station_tanks(id) ON DELETE SET NULL;

-- 3. Add opening_stock to station_tanks
ALTER TABLE public.station_tanks
  ADD COLUMN opening_stock numeric DEFAULT 0;

-- 4. Rework station_banks into lodgements
--    Add lodgement_type (POS, Bank Deposit, Cash, etc.), terminal_id, balance
ALTER TABLE public.station_banks
  ADD COLUMN lodgement_type text NOT NULL DEFAULT 'bank_deposit'
    CHECK (lodgement_type IN ('pos', 'bank_deposit', 'cash', 'other')),
  ADD COLUMN terminal_id text,
  ADD COLUMN balance numeric DEFAULT 0;


-- ─────────────────────────────────────────────
-- 013_password_auth.sql
-- ─────────────────────────────────────────────

-- Switch from PIN to password auth
-- Add password_hash, must_change_password flag
-- Keep pin_hash temporarily for backward compat (can drop later)

ALTER TABLE public.users
  ADD COLUMN password_hash text,
  ADD COLUMN must_change_password boolean NOT NULL DEFAULT false;


-- ─────────────────────────────────────────────
-- 014_wacart_subscription_flow.sql
-- ─────────────────────────────────────────────

-- Wacart-style subscription flow
-- New statuses: pending_payment, pending_approval, approved, rejected
-- New columns: reference_code, payment_deadline

-- 1. Drop the old status constraint and add new one
ALTER TABLE public.subscriptions
  DROP CONSTRAINT IF EXISTS subscriptions_status_check;

ALTER TABLE public.subscriptions
  ADD CONSTRAINT subscriptions_status_check
  CHECK (status IN ('pending_payment', 'pending_approval', 'approved', 'expired', 'rejected'));

-- 2. Migrate existing data to new statuses
UPDATE public.subscriptions SET status = 'pending_payment' WHERE status = 'pending';
UPDATE public.subscriptions SET status = 'approved' WHERE status = 'active';
UPDATE public.subscriptions SET status = 'rejected' WHERE status = 'revoked';

-- 3. Add new columns
ALTER TABLE public.subscriptions
  ADD COLUMN IF NOT EXISTS reference_code text,
  ADD COLUMN IF NOT EXISTS payment_deadline timestamptz;

-- 4. Index on reference_code for lookup
CREATE INDEX IF NOT EXISTS idx_subscriptions_reference_code ON public.subscriptions(reference_code);

-- 5. Allow users to update their own subscriptions (for proof upload)
drop policy if exists "users_update_own_subs" on public.subscriptions;
CREATE POLICY "users_update_own_subs" ON public.subscriptions
  FOR UPDATE USING (auth.uid() = user_id);


