-- ─────────────────────────────────────────────
-- 032_default_accounts.sql
-- ─────────────────────────────────────────────

-- Backfill default accounts for all existing stations.
-- Default accounts have phone = 'DEFAULT' and cannot be deleted via UI.

DO $$
DECLARE
  org RECORD;
  acct TEXT;
  i INT;
  accounts TEXT[] := ARRAY[
    'Police',
    'Manager Car',
    'DSS OFFICIALS',
    'Army',
    'EDSTMA',
    'Weight and Measures',
    'Vigilante',
    'Security Agents',
    'Regional Manager Car',
    'Area Manager Car',
    'LOGISTICS',
    'Pour Back After Pump Repairs',
    'Generator',
    'MDS Logistics Truck',
    'Logistics Truck',
    'Police/Army',
    'DPR',
    'Others',
    'Pour Back'
  ];
BEGIN
  FOR org IN SELECT id FROM organizations LOOP
    i := 1000;
    FOREACH acct IN ARRAY accounts LOOP
      -- Only insert if this default account doesn't already exist for the org
      INSERT INTO station_customers (org_id, name, phone, opening_balance, opening_date, sort_order)
      SELECT org.id, acct, 'DEFAULT', 0, CURRENT_DATE, i
      WHERE NOT EXISTS (
        SELECT 1 FROM station_customers
        WHERE org_id = org.id AND name = acct AND phone = 'DEFAULT'
      );
      i := i + 1;
    END LOOP;
  END LOOP;
END $$;


-- ─────────────────────────────────────────────
-- 033_station_messages_deleted_at.sql
-- ─────────────────────────────────────────────

-- Add deleted_at column to station_messages for soft-delete support
-- Also allow content to be nullable (null = deleted message)
--
-- The CREATE below is a repair, not new work. station_messages was created directly against
-- production and never written as a migration, so this file ALTERed a table that nothing in
-- supabase/migrations/ ever made. Applying the folder to a fresh database failed here with
-- 42P01 "relation station_messages does not exist", which is how it was found: rebuilding the
-- schema after the public schema was dropped.
--
-- It belongs here rather than in a later migration because 034+ would run after these ALTERs.
-- Shape is taken from the contract documented in app/api/chat/route.js and confirmed against
-- the live rows. IF NOT EXISTS so this stays a no-op on every database that already has it.

CREATE TABLE IF NOT EXISTS station_messages (
  id           UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id       UUID NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
  user_id      UUID REFERENCES users(id),
  user_name    TEXT,
  type         TEXT NOT NULL DEFAULT 'message',   -- 'message' | 'activity'
  content      TEXT,                              -- nullable (null = deleted)
  action_type  TEXT,                              -- e.g. 'created_entry', 'left_station'
  deleted_at   TIMESTAMPTZ,
  created_at   TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_station_messages_org_created
  ON station_messages (org_id, created_at DESC);

-- Locked with no policies: the chat API reaches this table with the service-role key.
ALTER TABLE station_messages ENABLE ROW LEVEL SECURITY;

ALTER TABLE station_messages ALTER COLUMN content DROP NOT NULL;
ALTER TABLE station_messages ADD COLUMN IF NOT EXISTS deleted_at TIMESTAMPTZ;


-- ─────────────────────────────────────────────
-- 034_default_lube_products.sql
-- ─────────────────────────────────────────────


-- Drop all existing lube products and replace with defaults for all stations.

DELETE FROM station_lube_products;

DO $$
DECLARE
  org RECORD;
  prod TEXT;
  i INT;
  products TEXT[] := ARRAY[
    'RAINOIL SUPREME 4L',
    'RAINOIL UNIVERSAL SAE 40 4L',
    'RAINOIL UNIVERSAL SAE 40 25L',
    'MAGNATEC 10W-40 4L',
    'INJECTOR CLEANER',
    'MAGNATEC 5W-30 1L',
    'MAGNATEC 5W-30 4L',
    'MAGNATEC 5W-30 A5',
    'RAINOIL SUPREME 1L',
    'RADICOOL',
    'BRAKE FLUID DOT 4 0.2L',
    'BRAKE FLUID DOT 4 0.5L',
    'GT X ESSENTIAL 20W-50 1L',
    'GT X ESSENTIAL 20W-50 4L',
    'POWER RACING 40 10W-50',
    'MOTOR OIL SAE 40',
    'EDGE PROFESSIONAL',
    'GT X ESSENTIAL 15W-40 4L',
    'GT X ESSENTIAL 15W-40 5L',
    'POWER MAX HD-40 (RETAIL OIL)',
    'ATF DEX II'
  ];
BEGIN
  FOR org IN SELECT id FROM organizations LOOP
    i := 0;
    FOREACH prod IN ARRAY products LOOP
      INSERT INTO station_lube_products (org_id, product_name, unit_price, opening_stock, opening_date, sort_order)
      VALUES (org.id, prod, 0, 0, CURRENT_DATE, i);
      i := i + 1;
    END LOOP;
  END LOOP;
END $$;


-- ─────────────────────────────────────────────
-- 035_backfill_subscription_org_id.sql
-- ─────────────────────────────────────────────

-- Backfill org_id on existing subscriptions where it's NULL.
-- Set it to the owner's first organization.

UPDATE subscriptions s
SET org_id = (
  SELECT o.id
  FROM organizations o
  WHERE o.owner_id = s.user_id
  ORDER BY o.created_at ASC
  LIMIT 1
)
WHERE s.org_id IS NULL;


-- ─────────────────────────────────────────────
-- 036_pg_cron_expire_subscriptions.sql
-- ─────────────────────────────────────────────

-- Replace Vercel cron with pg_cron for expiring subscriptions.
-- Runs daily at 03:00 UTC entirely inside Postgres — no serverless function needed.

-- Enable pg_cron extension (already available on all Supabase plans)
CREATE EXTENSION IF NOT EXISTS pg_cron;

-- Remove any existing schedule with this name before creating
SELECT cron.unschedule('expire-subscriptions') WHERE EXISTS (
  SELECT 1 FROM cron.job WHERE jobname = 'expire-subscriptions'
);

SELECT cron.schedule(
  'expire-subscriptions',
  '0 3 * * *',
  $$
    -- Expire approved subscriptions whose end_date has passed
    UPDATE public.subscriptions
    SET status = 'expired'
    WHERE status = 'approved'
      AND end_date < CURRENT_DATE;

    -- Expire pending_payment subscriptions whose payment_deadline has passed
    UPDATE public.subscriptions
    SET status = 'expired'
    WHERE status = 'pending_payment'
      AND payment_deadline < NOW();
  $$
);


-- ─────────────────────────────────────────────
-- 037_pg_cron_consolidate.sql
-- ─────────────────────────────────────────────

-- Replaces the Vercel /api/cron/consolidate route with a pg_cron job.
-- Runs entirely inside Postgres — no Edge Function or CLI needed.
-- Paste into Supabase SQL Editor and run once.

CREATE OR REPLACE FUNCTION public.consolidate_entries()
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_cutoff      date := CURRENT_DATE - 90;
  v_new_opening date := CURRENT_DATE - 89;
BEGIN
  -- 1. Banks: roll lodgement totals into opening_balance
  UPDATE station_banks sb
  SET opening_balance = sb.opening_balance + agg.total,
      opening_date    = v_new_opening
  FROM (
    SELECT bank_id, SUM(amount) AS total
    FROM lodgement_entries
    WHERE entry_date < v_cutoff AND bank_id IS NOT NULL
    GROUP BY bank_id
  ) agg
  WHERE sb.id = agg.bank_id;

  -- 2. Lube products: roll net stock movement (received - sold) into opening_stock
  UPDATE station_lube_products
  SET opening_stock = opening_stock + agg.net,
      opening_date  = v_new_opening
  FROM (
    SELECT product_id, SUM(unit_received - unit_sold) AS net
    FROM lube_sales_entries
    WHERE entry_date < v_cutoff AND product_id IS NOT NULL
    GROUP BY product_id
  ) agg
  WHERE id = agg.product_id;

  -- 3. Customers: roll net balance (sales - payments) into opening_balance
  UPDATE station_customers
  SET opening_balance = opening_balance + agg.net,
      opening_date    = v_new_opening
  FROM (
    SELECT customer_id, SUM(sales_amount - amount_paid) AS net
    FROM customer_payment_entries
    WHERE entry_date < v_cutoff AND customer_id IS NOT NULL
    GROUP BY customer_id
  ) agg
  WHERE id = agg.customer_id;

  -- 4. Tanks: roll product receipt volumes into opening_stock
  UPDATE station_tanks
  SET opening_stock = opening_stock + agg.total,
      opening_date  = v_new_opening
  FROM (
    SELECT tank_id, SUM(actual_volume) AS total
    FROM product_receipt_entries
    WHERE entry_date < v_cutoff AND tank_id IS NOT NULL
    GROUP BY tank_id
  ) agg
  WHERE id = agg.tank_id;

  -- 5. Nozzle readings: deduct net sold from tanks, then advance pump initial_reading.
  --    Tank deduction must happen BEFORE we update pump initial_reading (it's the baseline).

  -- 5a. Aggregate max closing_meter and total pour_back per pump from old entries
  CREATE TEMP TABLE _pump_agg ON COMMIT DROP AS
  SELECT
    (nr->>'pump_id')::uuid                                 AS pump_id,
    MAX((nr->>'closing_meter')::numeric)                   AS max_meter,
    SUM(COALESCE((nr->>'pour_back')::numeric, 0))          AS total_pour_back
  FROM daily_sales_entries,
       LATERAL jsonb_array_elements(nozzle_readings) AS nr
  WHERE entry_date < v_cutoff
    AND nozzle_readings IS NOT NULL
    AND jsonb_array_length(nozzle_readings) > 0
    AND (nr->>'pump_id') IS NOT NULL
  GROUP BY (nr->>'pump_id')::uuid;

  -- 5b. Deduct net sold per tank using current pump initial_reading as baseline
  UPDATE station_tanks st
  SET opening_stock = opening_stock - deduct.total
  FROM (
    SELECT sp.tank_id,
           SUM(GREATEST(pa.max_meter - sp.initial_reading, 0) - pa.total_pour_back) AS total
    FROM _pump_agg pa
    JOIN station_pumps sp ON sp.id = pa.pump_id
    WHERE sp.tank_id IS NOT NULL
    GROUP BY sp.tank_id
  ) deduct
  WHERE st.id = deduct.tank_id AND deduct.total > 0;

  -- 5c. Advance pump initial_reading to max closing_meter
  UPDATE station_pumps sp
  SET initial_reading = pa.max_meter,
      opening_date    = v_new_opening
  FROM _pump_agg pa
  WHERE sp.id = pa.pump_id;

  -- 6. Delete old entries from all 6 tables
  DELETE FROM daily_sales_entries      WHERE entry_date < v_cutoff;
  DELETE FROM product_receipt_entries  WHERE entry_date < v_cutoff;
  DELETE FROM lodgement_entries        WHERE entry_date < v_cutoff;
  DELETE FROM lube_sales_entries       WHERE entry_date < v_cutoff;
  DELETE FROM lube_stock_entries       WHERE entry_date < v_cutoff;
  DELETE FROM customer_payment_entries WHERE entry_date < v_cutoff;

  RETURN jsonb_build_object('ok', true, 'cutoff', v_cutoff);
END;
$$;

-- Schedule: every Sunday at 02:00 UTC
SELECT cron.unschedule('consolidate') WHERE EXISTS (
  SELECT 1 FROM cron.job WHERE jobname = 'consolidate'
);

SELECT cron.schedule(
  'consolidate',
  '0 2 * * 0',
  $$ SELECT public.consolidate_entries(); $$
);


