-- ─────────────────────────────────────────────
-- 042_reset_nozzle_consumption.sql
-- ─────────────────────────────────────────────

-- Reset all consumption, pour_back, and consumption_customer_id on nozzle readings
-- so they can be re-entered fresh from the daily sales form.
UPDATE daily_sales_entries
SET nozzle_readings = (
  SELECT jsonb_agg(
    elem - 'consumption' - 'pour_back' - 'consumption_customer_id'
    || jsonb_build_object('consumption', 0, 'pour_back', 0, 'consumption_customer_id', null)
  )
  FROM jsonb_array_elements(nozzle_readings) AS elem
),
updated_at = now()
WHERE nozzle_readings IS NOT NULL
  AND jsonb_array_length(nozzle_readings) > 0;


-- ─────────────────────────────────────────────
-- 043_soft_delete_entries.sql
-- ─────────────────────────────────────────────

-- Add deleted_at column to all 6 entry tables for soft-delete support.
-- This enables the poll endpoint to propagate deletions across devices.

ALTER TABLE daily_sales_entries ADD COLUMN deleted_at timestamptz DEFAULT NULL;
ALTER TABLE product_receipt_entries ADD COLUMN deleted_at timestamptz DEFAULT NULL;
ALTER TABLE lodgement_entries ADD COLUMN deleted_at timestamptz DEFAULT NULL;
ALTER TABLE lube_sales_entries ADD COLUMN deleted_at timestamptz DEFAULT NULL;
ALTER TABLE lube_stock_entries ADD COLUMN deleted_at timestamptz DEFAULT NULL;
ALTER TABLE customer_payment_entries ADD COLUMN deleted_at timestamptz DEFAULT NULL;

-- Index for efficient polling: find soft-deleted records by updated_at
CREATE INDEX idx_daily_sales_deleted ON daily_sales_entries(updated_at) WHERE deleted_at IS NOT NULL;
CREATE INDEX idx_product_receipt_deleted ON product_receipt_entries(updated_at) WHERE deleted_at IS NOT NULL;
CREATE INDEX idx_lodgement_deleted ON lodgement_entries(updated_at) WHERE deleted_at IS NOT NULL;
CREATE INDEX idx_lube_sales_deleted ON lube_sales_entries(updated_at) WHERE deleted_at IS NOT NULL;
CREATE INDEX idx_lube_stock_deleted ON lube_stock_entries(updated_at) WHERE deleted_at IS NOT NULL;
CREATE INDEX idx_customer_payment_deleted ON customer_payment_entries(updated_at) WHERE deleted_at IS NOT NULL;


-- ─────────────────────────────────────────────
-- 044_soft_delete_consolidate.sql
-- ─────────────────────────────────────────────

-- Update consolidate_entries() to exclude soft-deleted entries from aggregations
-- and to hard-delete both old entries and soft-deleted entries during cleanup.

CREATE OR REPLACE FUNCTION public.consolidate_entries()
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_cutoff      date := CURRENT_DATE - 90;
  v_new_opening date := CURRENT_DATE - 89;
BEGIN
  -- 1. Banks: roll lodgement totals into opening_balance
  UPDATE station_banks sb
  SET opening_balance = sb.opening_balance + agg.total,
      opening_date    = v_new_opening
  FROM (
    SELECT bank_id, SUM(amount) AS total
    FROM lodgement_entries
    WHERE entry_date < v_cutoff AND bank_id IS NOT NULL AND deleted_at IS NULL
    GROUP BY bank_id
  ) agg
  WHERE sb.id = agg.bank_id;

  -- 2. Lube products: roll net stock movement (received - sold) into opening_stock
  UPDATE station_lube_products
  SET opening_stock = opening_stock + agg.net,
      opening_date  = v_new_opening
  FROM (
    SELECT product_id, SUM(unit_received - unit_sold) AS net
    FROM lube_sales_entries
    WHERE entry_date < v_cutoff AND product_id IS NOT NULL AND deleted_at IS NULL
    GROUP BY product_id
  ) agg
  WHERE id = agg.product_id;

  -- 3. Customers: roll net balance (sales - payments) into opening_balance
  UPDATE station_customers
  SET opening_balance = opening_balance + agg.net,
      opening_date    = v_new_opening
  FROM (
    SELECT customer_id, SUM(sales_amount - amount_paid) AS net
    FROM customer_payment_entries
    WHERE entry_date < v_cutoff AND customer_id IS NOT NULL AND deleted_at IS NULL
    GROUP BY customer_id
  ) agg
  WHERE id = agg.customer_id;

  -- 4. Tanks: roll product receipt volumes into opening_stock
  UPDATE station_tanks
  SET opening_stock = opening_stock + agg.total,
      opening_date  = v_new_opening
  FROM (
    SELECT tank_id, SUM(actual_volume) AS total
    FROM product_receipt_entries
    WHERE entry_date < v_cutoff AND tank_id IS NOT NULL AND deleted_at IS NULL
    GROUP BY tank_id
  ) agg
  WHERE id = agg.tank_id;

  -- 5. Nozzle readings: deduct net sold from tanks, then advance pump initial_reading.
  CREATE TEMP TABLE _pump_agg ON COMMIT DROP AS
  SELECT
    (nr->>'pump_id')::uuid                                 AS pump_id,
    MAX((nr->>'closing_meter')::numeric)                   AS max_meter,
    SUM(COALESCE((nr->>'pour_back')::numeric, 0))          AS total_pour_back
  FROM daily_sales_entries,
       LATERAL jsonb_array_elements(nozzle_readings) AS nr
  WHERE entry_date < v_cutoff
    AND deleted_at IS NULL
    AND nozzle_readings IS NOT NULL
    AND jsonb_array_length(nozzle_readings) > 0
    AND (nr->>'pump_id') IS NOT NULL
  GROUP BY (nr->>'pump_id')::uuid;

  -- 5b. Deduct net sold per tank
  UPDATE station_tanks st
  SET opening_stock = opening_stock - deduct.total
  FROM (
    SELECT sp.tank_id,
           SUM(GREATEST(pa.max_meter - sp.initial_reading, 0) - pa.total_pour_back) AS total
    FROM _pump_agg pa
    JOIN station_pumps sp ON sp.id = pa.pump_id
    WHERE sp.tank_id IS NOT NULL
    GROUP BY sp.tank_id
  ) deduct
  WHERE st.id = deduct.tank_id AND deduct.total > 0;

  -- 5c. Advance pump initial_reading
  UPDATE station_pumps sp
  SET initial_reading = pa.max_meter,
      opening_date    = v_new_opening
  FROM _pump_agg pa
  WHERE sp.id = pa.pump_id;

  -- 6. Hard-delete old entries (>90 days) AND any soft-deleted entries (>7 days)
  -- Old entries get consolidated above; soft-deleted entries are just garbage collected
  DELETE FROM daily_sales_entries      WHERE entry_date < v_cutoff OR (deleted_at IS NOT NULL AND deleted_at < NOW() - INTERVAL '7 days');
  DELETE FROM product_receipt_entries  WHERE entry_date < v_cutoff OR (deleted_at IS NOT NULL AND deleted_at < NOW() - INTERVAL '7 days');
  DELETE FROM lodgement_entries        WHERE entry_date < v_cutoff OR (deleted_at IS NOT NULL AND deleted_at < NOW() - INTERVAL '7 days');
  DELETE FROM lube_sales_entries       WHERE entry_date < v_cutoff OR (deleted_at IS NOT NULL AND deleted_at < NOW() - INTERVAL '7 days');
  DELETE FROM lube_stock_entries       WHERE entry_date < v_cutoff OR (deleted_at IS NOT NULL AND deleted_at < NOW() - INTERVAL '7 days');
  DELETE FROM customer_payment_entries WHERE entry_date < v_cutoff OR (deleted_at IS NOT NULL AND deleted_at < NOW() - INTERVAL '7 days');

  RETURN jsonb_build_object('ok', true, 'cutoff', v_cutoff);
END;
$$;


-- ─────────────────────────────────────────────
-- 045_product_receipt_times.sql
-- ─────────────────────────────────────────────

-- Add arrival_time and exit_time to product_receipt_entries
-- These are time-only TEXT fields (e.g. "14:30") for when the truck arrived at / left the station.

ALTER TABLE product_receipt_entries ADD COLUMN IF NOT EXISTS arrival_time TEXT;
ALTER TABLE product_receipt_entries ADD COLUMN IF NOT EXISTS exit_time TEXT;


-- ─────────────────────────────────────────────
-- 046_per_compartment_ullage.sql
-- ─────────────────────────────────────────────

-- Migration 046: Per-compartment ullage, liquid height, and volume fields
-- Old single-value columns are kept for backward compatibility.

ALTER TABLE product_receipt_entries
  -- Chart: highest ullage, lowest ullage (replaces old chart_ullage)
  ADD COLUMN IF NOT EXISTS chart_high_ullage_1 numeric DEFAULT 0,
  ADD COLUMN IF NOT EXISTS chart_high_ullage_2 numeric DEFAULT 0,
  ADD COLUMN IF NOT EXISTS chart_high_ullage_3 numeric DEFAULT 0,
  ADD COLUMN IF NOT EXISTS chart_low_ullage_1 numeric DEFAULT 0,
  ADD COLUMN IF NOT EXISTS chart_low_ullage_2 numeric DEFAULT 0,
  ADD COLUMN IF NOT EXISTS chart_low_ullage_3 numeric DEFAULT 0,
  -- Chart: liquid height per compartment
  ADD COLUMN IF NOT EXISTS chart_liquid_height_1 numeric DEFAULT 0,
  ADD COLUMN IF NOT EXISTS chart_liquid_height_2 numeric DEFAULT 0,
  ADD COLUMN IF NOT EXISTS chart_liquid_height_3 numeric DEFAULT 0,
  -- Depot: ullage per compartment
  ADD COLUMN IF NOT EXISTS depot_ullage_1 numeric DEFAULT 0,
  ADD COLUMN IF NOT EXISTS depot_ullage_2 numeric DEFAULT 0,
  ADD COLUMN IF NOT EXISTS depot_ullage_3 numeric DEFAULT 0,
  -- Depot: liquid height per compartment
  ADD COLUMN IF NOT EXISTS depot_liquid_height_1 numeric DEFAULT 0,
  ADD COLUMN IF NOT EXISTS depot_liquid_height_2 numeric DEFAULT 0,
  ADD COLUMN IF NOT EXISTS depot_liquid_height_3 numeric DEFAULT 0,
  -- Station: ullage per compartment
  ADD COLUMN IF NOT EXISTS station_ullage_1 numeric DEFAULT 0,
  ADD COLUMN IF NOT EXISTS station_ullage_2 numeric DEFAULT 0,
  ADD COLUMN IF NOT EXISTS station_ullage_3 numeric DEFAULT 0,
  -- Station: liquid height per compartment
  ADD COLUMN IF NOT EXISTS station_liquid_height_1 numeric DEFAULT 0,
  ADD COLUMN IF NOT EXISTS station_liquid_height_2 numeric DEFAULT 0,
  ADD COLUMN IF NOT EXISTS station_liquid_height_3 numeric DEFAULT 0,
  -- Compartment volumes: highest and lowest (replaces first/second/third_compartment)
  ADD COLUMN IF NOT EXISTS high_vol_1 numeric DEFAULT 0,
  ADD COLUMN IF NOT EXISTS high_vol_2 numeric DEFAULT 0,
  ADD COLUMN IF NOT EXISTS high_vol_3 numeric DEFAULT 0,
  ADD COLUMN IF NOT EXISTS low_vol_1 numeric DEFAULT 0,
  ADD COLUMN IF NOT EXISTS low_vol_2 numeric DEFAULT 0,
  ADD COLUMN IF NOT EXISTS low_vol_3 numeric DEFAULT 0;

-- Backfill: copy old single values into new per-compartment columns
UPDATE product_receipt_entries SET
  chart_high_ullage_1 = COALESCE(chart_ullage, 0),
  chart_liquid_height_1 = COALESCE(chart_liquid_height, 0),
  depot_ullage_1 = COALESCE(depot_ullage, 0),
  depot_liquid_height_1 = COALESCE(depot_liquid_height, 0),
  station_ullage_1 = COALESCE(station_ullage, 0),
  station_liquid_height_1 = COALESCE(station_liquid_height, 0),
  high_vol_1 = COALESCE(first_compartment, 0),
  high_vol_2 = COALESCE(second_compartment, 0),
  high_vol_3 = COALESCE(third_compartment, 0)
WHERE chart_high_ullage_1 = 0
  AND high_vol_1 = 0
  AND high_vol_2 = 0
  AND high_vol_3 = 0;


-- ─────────────────────────────────────────────
-- 047_imprest.sql
-- ─────────────────────────────────────────────

-- 047: Imprest (Petty Cash) tables
-- Monthly imprest periods + individual expense entries with receipt images

-- ── imprest_periods ─────────────────────────────────────────────────────────
create table if not exists imprest_periods (
  id            uuid primary key default gen_random_uuid(),
  org_id        uuid not null references organizations(id) on delete cascade,
  month         smallint not null check (month between 1 and 12),
  year          smallint not null check (year between 2020 and 2099),
  imprest_amount numeric(12,2) not null default 0,
  custodian_name text,
  form_number   text,
  notes         text,
  created_by    uuid references users(id) on delete set null,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  unique (org_id, month, year)
);

create index idx_imprest_periods_org on imprest_periods(org_id);

alter table imprest_periods enable row level security;

drop policy if exists "Users can view their org imprest periods" on imprest_periods;
create policy "Users can view their org imprest periods"
  on imprest_periods for select
  using (org_id in (select org_id from users where id = auth.uid()));

drop policy if exists "Users can insert imprest periods for their org" on imprest_periods;
create policy "Users can insert imprest periods for their org"
  on imprest_periods for insert
  with check (org_id in (select org_id from users where id = auth.uid()));

drop policy if exists "Users can update their org imprest periods" on imprest_periods;
create policy "Users can update their org imprest periods"
  on imprest_periods for update
  using (org_id in (select org_id from users where id = auth.uid()));

drop policy if exists "Admin full access imprest periods" on imprest_periods;
create policy "Admin full access imprest periods"
  on imprest_periods for all
  using (org_id = admin_org_id());

-- ── imprest_entries ─────────────────────────────────────────────────────────
create table if not exists imprest_entries (
  id                uuid primary key default gen_random_uuid(),
  org_id            uuid not null references organizations(id) on delete cascade,
  imprest_period_id uuid not null references imprest_periods(id) on delete cascade,
  entry_date        date not null,
  beneficiary       text not null,
  transaction_details text,
  amount            numeric(12,2) not null default 0,
  account_code      text,
  pcv_number        text,
  receipt_image_url text,
  created_by        uuid references users(id) on delete set null,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  deleted_at        timestamptz
);

create index idx_imprest_entries_org on imprest_entries(org_id);
create index idx_imprest_entries_period on imprest_entries(imprest_period_id);
create index idx_imprest_entries_date on imprest_entries(entry_date);

alter table imprest_entries enable row level security;

drop policy if exists "Users can view their org imprest entries" on imprest_entries;
create policy "Users can view their org imprest entries"
  on imprest_entries for select
  using (org_id in (select org_id from users where id = auth.uid()));

drop policy if exists "Users can insert imprest entries for their org" on imprest_entries;
create policy "Users can insert imprest entries for their org"
  on imprest_entries for insert
  with check (org_id in (select org_id from users where id = auth.uid()));

drop policy if exists "Users can update their own imprest entries" on imprest_entries;
create policy "Users can update their own imprest entries"
  on imprest_entries for update
  using (created_by = auth.uid());

drop policy if exists "Users can delete their own imprest entries" on imprest_entries;
create policy "Users can delete their own imprest entries"
  on imprest_entries for delete
  using (created_by = auth.uid());

drop policy if exists "Admin full access imprest entries" on imprest_entries;
create policy "Admin full access imprest entries"
  on imprest_entries for all
  using (org_id = admin_org_id());


