  ADD COLUMN IF NOT EXISTS station_value_tracked boolean NOT NULL DEFAULT false;


-- ─────────────────────────────────────────────
-- 052_daily_sales_cob_unique.sql
-- ─────────────────────────────────────────────

-- One close-of-business entry per station per day.
--
-- Duplicate-prevention for daily sales previously ran only against each device's local Dexie
-- mirror, which can be stale. An offline / out-of-date device could not see a day's existing
-- entry and so created a SECOND close-of-business row for it (this is what produced the
-- duplicate daily-sales rows on days entered twice from different devices, which then inflated
-- the reports). This enforces the rule at the database level, where a stale client cannot
-- bypass it. Multiple non-close-of-business SHIFT entries per day are still allowed.
--
-- IMPORTANT: any existing duplicate live close-of-business rows must be soft-deleted BEFORE
-- running this migration, otherwise the index creation fails with a uniqueness error. Find them
-- with:
--   SELECT org_id, entry_date, count(*) FROM daily_sales_entries
--   WHERE close_of_business IS TRUE AND deleted_at IS NULL
--   GROUP BY org_id, entry_date HAVING count(*) > 1;

CREATE UNIQUE INDEX IF NOT EXISTS uniq_daily_sales_one_cob_per_day
  ON daily_sales_entries (org_id, entry_date)
  WHERE close_of_business IS TRUE AND deleted_at IS NULL;


-- ─────────────────────────────────────────────
-- 053_admin_activity.sql
-- ─────────────────────────────────────────────

-- Audit trail for platform staff acting inside a station they do not own.
--
-- lib/stationAccess.js lets role='admin' reach EVERY station, which is what allows an admin
-- to run the setup wizard for an owner they are onboarding. That is a large amount of reach,
-- and the thing that makes it safe is not the permission check but this table: every write
-- an admin makes inside someone else's station leaves a row here.
--
-- Only WRITES are recorded, and only when the acting user neither owns nor staffs the
-- station. Logging reads would bury the real actions under page views on a busy station, and
-- logging an owner's own writes would make the log a duplicate of the data.
--
-- No FK on admin_id or org_id: the log must outlive whatever it describes. A station deleted
-- six months from now should not take the record of what was done to it.
--
-- Text ids to match the rest of this schema. RLS on with no policies — the server reaches it
-- with the service-role key, and nothing client-side should ever read it directly.
--
-- MANUAL MIGRATION: station-portal migrations are applied by hand. Run this on production
-- BEFORE the routes start honouring admin access, or admin-on-behalf writes will happen with
-- no record of them.

CREATE TABLE IF NOT EXISTS admin_activity_logs (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  admin_id    uuid,                    -- users.id of the acting staff member
  admin_name  text DEFAULT '',         -- denormalised: the log must still read if the account goes
  org_id      uuid,                    -- the station acted upon
  org_name    text DEFAULT '',         -- denormalised for the same reason
  action_type text DEFAULT '',         -- e.g. 'onboarding_saved', 'station_assist'
  target_type text DEFAULT '',
  target_id   text,
  content     text NOT NULL,           -- the sentence that reads after the admin's name
  details     jsonb,                   -- request method + path; NEVER secrets, read back verbatim
  created_at  timestamptz DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_admin_activity_created ON admin_activity_logs (created_at DESC);
CREATE INDEX IF NOT EXISTS idx_admin_activity_org ON admin_activity_logs (org_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_admin_activity_admin ON admin_activity_logs (admin_id, created_at DESC);

ALTER TABLE admin_activity_logs ENABLE ROW LEVEL SECURITY;


-- ─────────────────────────────────────────────
-- 054_station_group_fk.sql
-- ─────────────────────────────────────────────

-- Station groups keyed by id instead of matched by name.
--
-- Before: organizations.station_group held a TEXT group name, and station_groups was unique
-- per (owner_id, name). Two admins could each own a group called "Lagos", the text sitting on
-- a station matched neither of them in particular, and deleting one admin's "Lagos" unset the
-- stations belonging to the other's. Cleanup on delete was also done in a route handler, which
-- meant it only ran when that handler ran.
--
-- After: organizations.station_group_id references station_groups(id) ON DELETE SET NULL. The
-- link is exact, and cleanup happens in the database whatever deletes the row.
--
-- organizations.station_group (text) is LEFT IN PLACE deliberately. Dropping it here breaks the
-- running app for the window between this migration and the deploy that stops reading it.
-- Application code stops reading and writing it from that deploy on; drop it in a later
-- migration once this is live and settled.

begin;

-- 1. Groups become platform-wide, because the admin screen that manages them manages every
--    station on the platform rather than the admin's own. A global unique name needs the
--    per-owner duplicates collapsed first: keep the oldest row for each name, with id breaking
--    any tie on created_at so the comparison is a total order and one row always survives.
delete from public.station_groups g
using public.station_groups keep
where g.name = keep.name
  and (g.created_at, g.id) > (keep.created_at, keep.id);

alter table public.station_groups drop constraint if exists station_groups_owner_id_name_key;
alter table public.station_groups alter column owner_id drop not null;

create unique index if not exists station_groups_name_key
  on public.station_groups (name);

comment on column public.station_groups.owner_id is
  'The admin who created the group. Groups are platform-wide, so this is provenance, not scope.';

-- 2. The link itself. ON DELETE SET NULL is what replaces the handler that used to unset the
--    text column by name.
alter table public.organizations
  add column if not exists station_group_id uuid
  references public.station_groups(id) on delete set null;

create index if not exists organizations_station_group_id_idx
  on public.organizations (station_group_id);

-- 3. Backfill from whatever names were already assigned. Anything whose text does not match a
--    surviving group is left null, which is the honest result: that group did not exist.
--
--    Guarded on the column existing. Migrations here are applied by hand, and prod was found
--    to be missing 026 and 027 entirely, so this cannot assume the text column is there. With
--    no column there is also nothing to backfill, and skipping is correct rather than a
--    fallback.
do $$
begin
  if exists (
    select 1 from information_schema.columns
    where table_schema = 'public'
      and table_name = 'organizations'
      and column_name = 'station_group'
  ) then
    update public.organizations o
    set station_group_id = g.id
    from public.station_groups g
    where o.station_group_id is null
      and o.station_group is not null
      and o.station_group = g.name;
  end if;
end $$;

-- 4. RLS. Every application read and write goes through the service role and bypasses this
--    entirely; the policy is the backstop for anything arriving with a user's own token. The
--    old policy scoped rows to owner_id = auth.uid(), which no longer describes the table.
drop policy if exists "Users can manage their own groups" on public.station_groups;

drop policy if exists "Admins manage station groups" on public.station_groups;
create policy "Admins manage station groups"
  on public.station_groups
  for all
  using (exists (select 1 from public.users u where u.id = auth.uid() and u.role = 'admin'))
  with check (exists (select 1 from public.users u where u.id = auth.uid() and u.role = 'admin'));

commit;


-- ─────────────────────────────────────────────
-- 055_subscription_items_service_fk.sql
-- ─────────────────────────────────────────────

-- Point subscription_items.service_id at the services catalogue it actually holds.
--
-- 017 created the column as `references public.org_services(id)`, and nothing since corrected
-- it. org_services is a per-org list (org_id, name, description, sort_order) and has no
-- relationship to public.services, the platform catalogue every code path actually reads:
--
--   app/api/subscriptions/route.js         items built from the services list
--   app/api/admin/grant-subscription       .from('services')
--   lib/entryHelpers.js                    matches subscription_items.service_id to services.id
--
-- So on a database built from this folder, subscribing inserts a services.id into a column
-- constrained to org_services and fails with a foreign-key violation. Production evidently had
-- the constraint repointed by hand and it was never written down, so the drift only surfaced
-- when the schema was rebuilt from the migrations.
--
-- The constraint is looked up rather than named, because a by-hand fix may have left a name
-- other than the Postgres default.

do $$
declare
  conname_found text;
begin
  select con.conname into conname_found
  from pg_constraint con
  join pg_class rel on rel.oid = con.conrelid
  join pg_namespace ns on ns.oid = rel.relnamespace
  where ns.nspname = 'public'
    and rel.relname = 'subscription_items'
    and con.contype = 'f'
    and con.conkey = array[
      (select attnum from pg_attribute where attrelid = rel.oid and attname = 'service_id')
    ];

  if conname_found is not null then
    execute format('alter table public.subscription_items drop constraint %I', conname_found);
  end if;
end $$;

alter table public.subscription_items
  add constraint subscription_items_service_id_fkey
  foreign key (service_id) references public.services(id) on delete cascade;


-- ─────────────────────────────────────────────
-- 056_desktop_devices.sql
-- ─────────────────────────────────────────────

-- StationMGR Desktop: the computers linked to a station.
--
-- The desktop app (desktop/* branches) runs offline. Its owner links it to their web station
-- once, online (POST /api/desktop/link); after that it pushes and pulls the station's records
-- with a device token, and checks the station's subscriptions offline from a signed licence the
-- web hands it on every link, push and pull.
--
-- Only a hash of the token is kept: the token itself is shown to the computer once and never
-- stored here. Revoking a computer (revoked_at) stops its pushes, pulls and licence renewals.
--
-- RLS on with no policies: the server reaches it with the service-role key only.
--
-- MANUAL MIGRATION: run this on production before shipping a desktop build that links.

CREATE TABLE IF NOT EXISTS desktop_devices (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  org_id        uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
  user_id       uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,  -- the owner who linked it
  name          text DEFAULT '',                                         -- the computer's name, as reported
  token_hash    text NOT NULL UNIQUE,                                    -- sha256 of the device token
  created_at    timestamptz DEFAULT now(),
  last_seen_at  timestamptz,
  revoked_at    timestamptz
);

CREATE INDEX IF NOT EXISTS idx_desktop_devices_org ON desktop_devices (org_id);

ALTER TABLE desktop_devices ENABLE ROW LEVEL SECURITY;


-- ─────────────────────────────────────────────
-- 057_lube_entry_parties.sql
-- ─────────────────────────────────────────────

-- ============================================
-- 057: Who a lube entry was with, and a receipt's paperwork
-- ============================================
-- A lube sale can be on an account (customer_id): its amount (unit_sold x price) then counts
-- in that account's balance, as a credit sale does. A lube receipt (a lube entry with only
-- units received) names its supplier, also an account (supplier_id), its invoice or waybill
-- number (invoice_no) and what each unit cost (unit_cost). All four are optional, so every
-- existing entry stays as it is. Removing an account keeps the entry and drops the link.

ALTER TABLE lube_sales_entries
  ADD COLUMN IF NOT EXISTS customer_id uuid REFERENCES station_customers(id) ON DELETE SET NULL,
  ADD COLUMN IF NOT EXISTS supplier_id uuid REFERENCES station_customers(id) ON DELETE SET NULL,
  ADD COLUMN IF NOT EXISTS invoice_no text,
  ADD COLUMN IF NOT EXISTS unit_cost numeric;

CREATE INDEX IF NOT EXISTS idx_lube_sales_customer ON lube_sales_entries(customer_id);


-- ─────────────────────────────────────────────
-- 058_entry_updated_by.sql
-- ─────────────────────────────────────────────

-- ============================================
-- 058: Who last changed an entry
-- ============================================
-- The Notifications screen is gone; who did what is shown under each entry instead. An entry
-- already says who added it (created_by) and when it last changed (updated_at). updated_by
-- says who: set by every edit and every delete (a soft delete, deleted_at) in
-- app/api/entries/*. Existing entries keep it empty until their next change. Removing a user
-- keeps the entry and drops the name, as created_by on imprest_entries does.

ALTER TABLE daily_sales_entries
  ADD COLUMN IF NOT EXISTS updated_by uuid REFERENCES users(id) ON DELETE SET NULL;

ALTER TABLE product_receipt_entries
  ADD COLUMN IF NOT EXISTS updated_by uuid REFERENCES users(id) ON DELETE SET NULL;

ALTER TABLE lodgement_entries
  ADD COLUMN IF NOT EXISTS updated_by uuid REFERENCES users(id) ON DELETE SET NULL;

ALTER TABLE lube_sales_entries
  ADD COLUMN IF NOT EXISTS updated_by uuid REFERENCES users(id) ON DELETE SET NULL;

ALTER TABLE lube_stock_entries
  ADD COLUMN IF NOT EXISTS updated_by uuid REFERENCES users(id) ON DELETE SET NULL;

ALTER TABLE customer_payment_entries
  ADD COLUMN IF NOT EXISTS updated_by uuid REFERENCES users(id) ON DELETE SET NULL;

-- Not consumption_entries: the live database has no such table (migration 024 never reached
-- it) and nothing uses it now (lib/consumptionCalculations.js).

ALTER TABLE imprest_entries
  ADD COLUMN IF NOT EXISTS updated_by uuid REFERENCES users(id) ON DELETE SET NULL;

-- 059_ago_reset_date.sql
-- The Summary report's AGO sheet (tap the date five times) lists each day's highest AGO price
-- times 3 litres from this date on. Reset sets it to the day it is pressed, for every phone.
ALTER TABLE public.organizations
  ADD COLUMN IF NOT EXISTS ago_reset_date date;
